<div class="form-card"><p class="eyebrow">Inventory</p><h1><?= esc(isset($product['id'])?'Edit Product':'Create Product') ?></h1><?php if($errors): ?><div class="errors"><ul><?php foreach($errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" enctype="multipart/form-data" action="<?= site_url(isset($product['id'])?'products/'.$product['id'].'/edit':'products/new') ?>"><label for="name">Product Name</label><input id="name" name="name" value="<?= esc(old('name',$product['name']??'')) ?>" required><label for="price">Price</label><input id="price" name="price" type="number" min="0" step="0.01" value="<?= esc(old('price',$product['price']??'')) ?>" required><label for="stock_quantity">Stock Quantity</label><input id="stock_quantity" name="stock_quantity" type="number" min="0" step="1" value="<?= esc(old('stock_quantity',$product['stock_quantity']??'')) ?>" required><label for="image">Image (JPG or PNG, maximum 2 MB)</label><input id="image" name="image" type="file" accept="image/jpeg,image/png"><div class="form-actions"><button class="button" type="submit">Save Product</button><a class="button button-secondary" href="<?= site_url('products') ?>">Cancel</a></div></form></div>
